kid.example:
-- Script (Studio only, e.g. inside a plugin)
local HttpService = game:GetService("HttpService")

local client = HttpService:CreateWebStreamClient(Enum.WebStreamClientType.RawStream, {
	Url = "https://example.com/stream",
	Method = "GET",
})

client.MessageReceived:Connect(function(message)
	print("Got a piece:", message)
end)

-- When finished: client:Close()

-- Script in ServerScriptService
local HttpService = game:GetService("HttpService")

local ok, body = pcall(function()
	return HttpService:GetAsync("https://httpbin.org/get")
end)
print(ok, body)

examples.code:
local HttpService = game:GetService("HttpService")

local inventory = { coins = 10, items = { "Sword", "Shield" } }

local text = HttpService:JSONEncode(inventory)
print(text) --> something like {"coins":10,"items":["Sword","Shield"]}

local back = HttpService:JSONDecode(text)
print(back.items[1]) --> Sword

